// One next-generation map per game mode. Each is generated by levelgen.mjs from
// a deterministic seed and a small imperative layout, so the maps share an
// engine but not a silhouette. The legacy maps remain untouched in MAPS.
import {createLevel, mulberry32} from './levelgen.mjs';

const ring = (ctx, x, z, radius, count, place) => {
  for (let i = 0; i < count; i++) { const a = (i / count) * Math.PI * 2; place(ctx, x + Math.cos(a) * radius, z + Math.sin(a) * radius, a, i); }
};
const scatter = (ctx, count, rng, margin, place) => {
  for (let i = 0; i < count; i++) { const x = ctx.bounds.minX + margin + rng() * (ctx.bounds.maxX - ctx.bounds.minX - margin * 2), z = ctx.bounds.minZ + margin + rng() * (ctx.bounds.maxZ - ctx.bounds.minZ - margin * 2); place(ctx, x, z, i); }
};

// 1. Deathmatch — a grand stone colosseum with tiered seating and arches.
const colosseum = createLevel({
  id: 'colosseum', name: 'The Colosseum', tag: 'DEATHMATCH / STONE ARENA', color: '#d8b073', background: '#120e0b', seed: 1101,
  group: 'arena', scale: 'battle', mode: 'deathmatch', size: { w: 84, d: 84 }, biome: 'ruins', amplitude: 1.6, relief: .4,
  description: 'A tiered stone colosseum. Fight across the sand floor, up the ramps, and along the ring of arches.',
  layout(ctx, rng) {
    for (let tier = 0; tier < 4; tier++) {
      const r = 20 + tier * 6.5, h = 1.6 + tier * 1.4;
      ring(ctx, 0, 0, r, 24, (c, x, z, a, i) => {
        if (i % 6 < 2) return; // gaps keep the tiers walkable to bots
        if (i % 3 === 0 && tier < 3) c.addColumn({ x, z, y: c.ground(x, z), radius: .8, height: h + 4 });
        else c.addBlock({ x, z, w: 3.4, d: 3.4, h: c.ground(x, z) + h, kind: 'terrace' });
      });
    }
    for (let i = 0; i < 12; i++) { const a = (i / 12) * Math.PI * 2 + .26; ctx.addArch({ x: Math.cos(a) * 15, z: Math.sin(a) * 15, y: ctx.ground(Math.cos(a) * 15, Math.sin(a) * 15), width: 5.5, height: 6, rot: -a + Math.PI / 2 }); }
    for (let i = -1; i <= 1; i += 2) ctx.addBuilding({ x: i * 15, z: -16, w: 10, d: 8, h: 5, rot: i > 0 ? Math.PI / 2 : -Math.PI / 2, roof: 'flat', door: 'south', floors: 1 });
    scatter(ctx, 8, rng, 12, (c, x, z) => c.addRock({ x, z, scale: .6 + rng() * .5 }));
    ctx.addObjective(0, 0, 5); ctx.addObjective(-22, 0, 3.5); ctx.addObjective(22, 0, 3.5);
    for (let i = 0; i < 8; i++) { const a = (i / 8) * Math.PI * 2; ctx.addSpawn(Math.cos(a) * 9, Math.sin(a) * 9); }
    ctx.addPickup('rocket', -8, 0); ctx.addPickup('rail', 8, 0); ctx.addPickup('scatter', 0, -8); ctx.addPickup('plasma', 0, 8);
    ctx.addPickup('health', -24, 0); ctx.addPickup('health', 24, 0); ctx.addPickup('armor', 0, -24); ctx.addPickup('armor', 0, 24);
  },
});

// 2. Capture the Flag — two snow canyon bases linked by a tunnel and open ridges.
const frostGate = createLevel({
  id: 'frost-gate', name: 'Frost Gate', tag: 'CTF / SNOW CANYON', color: '#a9d8ff', background: '#0b1520', seed: 2202,
  group: 'outdoor', scale: 'warzone', mode: 'ctf', size: { w: 120, d: 80 }, biome: 'snow', amplitude: 8, relief: 2.4,
  description: 'A frozen canyon with walled bases, a central ice tunnel, and ridges that reward a long flank.',
  layout(ctx, rng) {
    ctx.teamSpawns = { 0: [[-38, -16], [-38, 16], [-46, -22], [-46, 22]], 1: [[38, 16], [38, -16], [46, 22], [46, -22]] };
    ctx.flagSpawns = { 0: { x: -48, z: 0 }, 1: { x: 48, z: 0 } };
    ctx.addBuilding({ x: -48, z: 0, w: 16, d: 18, h: 7, rot: Math.PI / 2, roof: 'gable', door: 'north', floors: 1, color: '#cfe8ff' });
    ctx.addBuilding({ x: 48, z: 0, w: 16, d: 18, h: 7, rot: -Math.PI / 2, roof: 'gable', door: 'north', floors: 1, color: '#cfe8ff' });
    ctx.addTunnel([[-34, undefined, 0], [-14, undefined, 0], [14, undefined, 0], [34, undefined, 0]], 3.2);
    ctx.addCavern({ x: 0, z: -20, radius: 13, height: 9 });
    // Reserve the tunnel and both mouths, including each prop's collision extent.
    const outsideTunnel = (x, z, radius) => Math.abs(x) > 40 + radius || Math.abs(z) > 3.2 + radius;
    ring(ctx, 0, 0, 26, 10, (c, x, z) => { const scale = 1.4 + rng() * 1.2; if (outsideTunnel(x, z, scale)) c.addRock({ x, z, scale }); });
    scatter(ctx, 22, rng, 8, (c, x, z) => { const tree = rng() > .45, scale = tree ? .9 + rng() * .6 : .7 + rng() * .6; if (outsideTunnel(x, z, tree ? .25 : scale)) (tree ? c.addTree : c.addRock)({ x, z, scale }); });
    ctx.addObjective(-30, 0, 3.5); ctx.addObjective(0, 0, 4); ctx.addObjective(30, 0, 3.5);
    ctx.addPickup('rail', 0, 22); ctx.addPickup('rocket', -18, -18); ctx.addPickup('rocket', 18, 18); ctx.addPickup('health', -48, 12); ctx.addPickup('health', 48, -12); ctx.addPickup('armor', 0, -20);
  },
});

