    for (const [x, z, rot] of [[-24, -24, 0], [24, 24, 0], [-24, 24, Math.PI], [24, -24, Math.PI]]) ctx.addBuilding({ x, z, w: 12, d: 10, h: 5, rot, roof: 'gable', door: 'south', floors: 1 });
